(function(){
function encode(snapshot){const s=snapshot.design,ids=[...new Set(s.cells.flat().filter(Boolean).map(c=>c.type))],values=s.cells.flat().map(c=>c?(ids.indexOf(c.type)+1)*4+c.rotation/90:0),runs=[];for(let i=0;i<values.length;){let j=i+1;while(j<values.length&&values[j]===values[i])j++;runs.push((j-i).toString(36)+'.'+values[i].toString(36));i=j}const data={v:1,d:[s.width,s.height,s.blockSize,s.joint,s.depth||100,s.sill||0,s.color],g:[s.cells.length,s.cells[0].length],b:ids,r:runs.join(','),c:s.combos||[],l:snapshot.lightStudy||null};const bytes=new TextEncoder().encode(JSON.stringify(data));if(bytes.length>90000)throw Error('This design is too large for a share link. Export its editable JSON instead.');let text='';for(const b of bytes)text+=String.fromCharCode(b);return btoa(text).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function decode(encoded){if(typeof encoded!=='string'||encoded.length>120000||!/^[A-Za-z0-9_-]+$/.test(encoded))throw Error('Invalid design link');const text=atob(encoded.replace(/-/g,'+').replace(/_/g,'/')),bytes=Uint8Array.from(text,c=>c.charCodeAt(0)),p=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));if(p.v!==1||!Array.isArray(p.d)||p.d.length!==7||!Array.isArray(p.g)||p.g.length!==2||!p.g.every(n=>Number.isInteger(n)&&n>=1)||p.g[0]*p.g[1]>8000||!Array.isArray(p.b)||p.b.length>100||!p.b.every(id=>typeof id==='string'&&id.length<60)||new Set(p.b).size!==p.b.length||typeof p.r!=='string'||!Array.isArray(p.c)||p.c.length>30)throw Error('Unsupported or invalid design link');const cells=[],total=p.g[0]*p.g[1];for(const run of p.r.split(',')){if(!/^[0-9a-z]+\.[0-9a-z]+$/.test(run))throw Error('Invalid design data');const [n,v]=run.split('.').map(x=>parseInt(x,36));if(!Number.isSafeInteger(n)||n<1||n>total||cells.length+n>total||!Number.isSafeInteger(v)||v<0||v>=4*(p.b.length+1)||v>0&&v<4)throw Error('Invalid design data');for(let k=0;k<n;k++)cells.push(v?{type:p.b[Math.floor(v/4)-1],rotation:(v%4)*90}:null)}if(cells.length!==total)throw Error('Incomplete design data');const [width,height,blockSize,joint,depth,sill,color]=p.d;return {design:{width,height,blockSize,joint,depth,sill,color,combos:p.c,preset:'',cells:Array.from({length:p.g[0]},(_,r)=>cells.slice(r*p.g[1],(r+1)*p.g[1]))},lightStudy:p.l}}
window.jaliShareCodec={encode,decode};
})();
